    methods=['private int calculationOperation(', 'private static int calculationButton(', 'public boolean handleButton(int id, ServerPlayer requester)','private boolean validCalculation(', 'private void processCalculation(', 'private void cancelForPackUp(', 'private boolean executeCalculation(', 'private SectorScan scanSurface(', 'private static List<Object> workTokens(', 'private void collectOreRow(', 'private void processBuildQueue(', 'private boolean placeQueueBlockNow(', 'private void processDismantleQueue(', 'private void processTntQueue(', 'private static void savePosList(', 'private static void loadPosList(']
    fields=text[text.index('    private final PlotnickTaskGate'):text.index('    private long intakeBudgetTick')]
    declarations='\n'.join(re.findall(r'(?:public|private) static final int (?:BTN_|TASK_)\w+ = \d+;',text))
